// Protected design (docs/DESIGN_CONTRACT.md). A failure here means the look, feel or flow changed.
// Do not edit these expectations or run design:approve without the owner's explicit approval in chat.
import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {designStatus,readLock,PROTECTED} from '../scripts/design_lock.mjs';
import {parseRoute} from '../dist/core.mjs';
import {CURRICULA} from '../dist/curricula.mjs';
import {createAppContext} from '../dist/domain/app-context.mjs';
const read=file=>fs.readFileSync(new URL(`../dist/${file}`,import.meta.url),'utf8');
const css=read('styles.css'),html=read('index.html'),app=read('app.mjs');
test('protected design files match the owner-approved lock',()=>{const {changed,missing}=designStatus();assert.deepEqual([...changed,...missing],[],'Protected design changed without approval. See docs/DESIGN_CONTRACT.md');const lock=readLock();assert.deepEqual(Object.keys(lock.files).sort(),[...PROTECTED].sort());assert.ok(lock.approvals.length>=1);for(const a of lock.approvals){assert.ok(a.reason&&a.approvedBy&&a.date&&a.files.length,'every approval names reason, approver, date and files');}});
test('TG palette keeps its values and roles (amended 1 Nov 2026: semantic tokens over ramps)',()=>{const root=css.match(/:root \{([\s\S]*?)\n\}/)[1];const tokens=Object.fromEntries([...root.matchAll(/(--[a-z0-9-]+):\s*([^;]+);/g)].map(m=>[m[1],m[2].trim()]));assert.deepEqual({blue:tokens['--blue-500'],blueDark:tokens['--blue-700'],ink:tokens['--neutral-900'],body:tokens['--neutral-700'],muted:tokens['--neutral-500'],bg:tokens['--neutral-50'],line:tokens['--neutral-300'],amber:tokens['--amber-500'],pink:tokens['--pink-500'],purple:tokens['--purple-500'],focus:tokens['--focus']},{blue:'#286f99',blueDark:'#174d6c',ink:'#253d4c',body:'#334d5c',muted:'#586c78',bg:'#f5f7f8',line:'#d4dfe5',amber:'#f0b35f',pink:'#df909d',purple:'#b5a0c9',focus:'#854900'});assert.deepEqual({brand:tokens['--color-brand'],teaching:tokens['--color-teaching'],practice:tokens['--color-practice'],support:tokens['--color-support'],focus:tokens['--color-focus']},{brand:'var(--blue-500)',teaching:'var(--amber-500)',practice:'var(--pink-500)',support:'var(--purple-500)',focus:'var(--focus)'});});
test('type scale, font, touch size and focus ring (amended 1 Nov 2026: self-hosted Noto, 13px minimum)',()=>{assert.match(css,/--font-sans: "Noto Sans Devanagari", "Noto Sans", system-ui/);assert.match(css,/body \{[^}]*font: var\(--fs-3\)\/var\(--lh-body\) var\(--font-sans\)/);for(const [k,v] of [['--fs-1','13px'],['--fs-3','17px'],['--fs-4','19px'],['--fs-5','23px'],['--fs-6','28px'],['--lh-body','1.65'],['--touch-min','48px']])assert.match(css,new RegExp(`${k}: ${v.replace('.','\\.')};`));assert.match(css,/--focus-ring: 3px solid var\(--color-focus\)/);assert.ok(fs.existsSync(new URL('../dist/fonts/noto-sans-devanagari.woff2',import.meta.url)));});
test('shell keeps Hindi default, skip link, three header links in order (आज · पूरा साल · सभी पाठ, owner-approved 1 Nov 2026), language menu and reader',()=>{assert.match(html,/<html lang="hi">/);assert.match(html,/<body><a class="skip-link" href="#main">/);const links=[...html.matchAll(/<a href="(#\/[a-z]+)" id="([a-z]+-link)"/g)].map(m=>[m[1],m[2]]);assert.deepEqual(links,[['#/today','today-link'],['#/guide','year-link'],['#/find','find-link']]);assert.match(html,/<select id="ui-language"[^>]*><option value="hi">हिन्दी<\/option><option value="en">English<\/option><\/select>/);for(const id of ['current-context','curriculum-navigation','main','toast'])assert.match(html,new RegExp(`id="${id}"`));assert.match(html,/<dialog id="reader"/);assert.equal(createAppContext({packs:CURRICULA,storage:null}).prefs.lang,'hi');});
test('routes and legacy deep links keep resolving',()=>{for(const screen of ['find','saved','help','today'])assert.equal(parseRoute(`#/${screen}`).screen,screen);assert.equal(parseRoute('').screen,'today');assert.equal(parseRoute('#/').screen,'today');assert.equal(parseRoute('#/unknown').screen,'find');assert.equal(parseRoute('#/lesson/g1-math-w09-d01').screen,'lesson');assert.equal(parseRoute('#/lesson/g1-math-w09-d01/teach/2').screen,'lesson');});
test('browse, lesson and action labels of the frozen flow are present',()=>{for(const label of ["t('आज','Today')","t('पूरा साल','Whole year')","t('सभी पाठ','All lessons')","t('मेरी सूची','My list')","t('मदद','Help')","t('पाठ के विषय से','By topic')","t('सप्ताह / दिन से','By week / day')","t('पाठयोजना खोलें','Open lesson overview')","t('साप्ताहिक रूपरेखा खोलें','Open weekly outline')","t('मेरा नोट','My teaching note')","t('मेरी तैयारी','My preparation')","t('पढ़ा दिया है · चिह्न लगाएँ','I have taught this · mark taught')","t('पढ़ाया गया चिह्न हटाएँ','Undo taught mark')",'class="section-chips"','class="guide-banner"','class="question-box"','data-mode="topic"','data-mode="week"'])assert.ok(app.includes(label),`app.mjs lost frozen UI element ${label}`);});
